package com.eventsync;
import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
import java.util.*; import java.util.stream.Collectors;
@RestController @RequestMapping("/api/me") public class VolunteerSelfController {
 private final AppUserRepository users; private final VolunteerRepository volunteers; private final AssignmentRepository assignments; private final TaskRepository tasks; private final EventRepository events;
 public VolunteerSelfController(AppUserRepository u,VolunteerRepository v,AssignmentRepository a,TaskRepository t,EventRepository e){users=u;volunteers=v;assignments=a;tasks=t;events=e;}
 private AppUser user(Authentication auth){return users.findByEmailIgnoreCase(auth.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
 @GetMapping("/profile") public Map<String,Object> profile(Authentication auth){AppUser u=user(auth); Volunteer v=volunteers.findById(u.volunteerId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));Map<String,Object> m=new LinkedHashMap<>();m.put("id",v.id);m.put("name",v.name);m.put("email",v.email);m.put("skills",v.skills);m.put("experience",v.experience);m.put("available",v.available);m.put("maxWorkload",v.maxWorkload);return m;}
 @GetMapping("/assignments") public List<Map<String,Object>> mine(Authentication auth){Long id=user(auth).volunteerId;return assignments.findByVolunteerIdAndStatus(id,"ASSIGNED").stream().map(a->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",a.id);m.put("status",a.status);m.put("assignedAt",a.assignedAt);EventTask t=tasks.findById(a.taskId).orElse(null);m.put("task",t==null?"Deleted task":t.title);m.put("description",t==null?"":t.description);m.put("workload",t==null?1:t.workload);m.put("event",t==null||t.eventId==null?"Event details unavailable":events.findById(t.eventId).map(e->e.name).orElse("Event details unavailable"));m.put("eventId",a.eventId);return m;}).collect(Collectors.toList());}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(Authentication auth){Long id=user(auth).volunteerId;List<Assignment> active=assignments.findByVolunteerIdAndStatus(id,"ASSIGNED");long completed=assignments.findByVolunteerIdAndStatus(id,"COMPLETED").size();int workload=active.stream().mapToInt(a->tasks.findById(a.taskId).map(t->t.workload).orElse(1)).sum();return Map.of("activeAssignments",active.size(),"completedAssignments",completed,"workload",workload);}
 @PostMapping("/assignments/{id}/complete") public Map<String,Object> complete(@PathVariable Long id,Authentication auth){Assignment a=assignments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!Objects.equals(a.volunteerId,user(auth).volunteerId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only update your own assignments.");a.status="COMPLETED";assignments.save(a);EventTask t=tasks.findById(a.taskId).orElse(null);if(t!=null){t.status="COMPLETED";tasks.save(t);}return Map.of("message","Task marked complete.");}
}
